import urllib.request, json, urllib.parse

def search_bing(query):
    url = 'https://cn.bing.com/search?q=' + urllib.parse.quote(query)
    req = urllib.request.Request(url, headers={'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64)'})
    try:
        html = urllib.request.urlopen(req, timeout=10).read().decode('utf-8', errors='ignore')
        from bs4 import BeautifulSoup
        soup = BeautifulSoup(html, 'html.parser')
        results = []
        for li in soup.find_all('li', class_='b_algo'):
            h2 = li.find('h2')
            snippet = li.find('p')
            if h2:
                title = h2.get_text()
                link = h2.find('a')['href'] if h2.find('a') else ''
                desc = snippet.get_text() if snippet else ''
                results.append({'title': title, 'link': link, 'snippet': desc})
        return results
    except Exception as e:
        return str(e)

print(json.dumps(search_bing('无锡 公积金 贷款 套数 认定 第三套'), ensure_ascii=False, indent=2)[:1000])
""
}

