import requests, lxml.html, urllib.parse

def baidu_search(query):
    url = 'https://m.baidu.com/s?word=' + urllib.parse.quote(query)
    headers = {'User-Agent': 'Mozilla/5.0 (iPhone; CPU iPhone OS 16_0 like Mac OS X) AppleWebKit/605.1.15 (KHTML, like Gecko) Version/16.0 Mobile/15E148 Safari/604.1'}
    r = requests.get(url, headers=headers, timeout=10)
    tree = lxml.html.fromstring(r.text)
    results = []
    for div in tree.xpath('//div[contains(@class, \"c-result\")]'):
        t = ''.join(div.xpath('.//text()')).strip()
        # clean up whitespaces
        t = ' '.join(t.split())
        if len(t) > 20 and not t.startswith('大家还在搜'):
            results.append(t)
    return results

print('=== 1. Wuxi Provident Fund Loan Housing Count ===')
for r in baidu_search('无锡 住房公积金 贷款管理办法 停止向购买第三套')[:3]:
    print(r[:200])

print('=== 2. Wuxi Tianyi Experimental Junior High Admission ===')
for r in baidu_search('无锡 天一实验学校 施教区 招生 户籍 房产证 截止时间')[:3]:
